ALTER TABLE members ADD COLUMN last_active_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP;
ALTER TABLE questions ADD COLUMN moderation_state TEXT NOT NULL DEFAULT 'visible' CHECK(moderation_state IN ('visible','pending','removed'));
CREATE TABLE moderation_reports(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id),question_id TEXT NOT NULL REFERENCES questions(id),reporter_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL DEFAULT 'pending',UNIQUE(question_id,reporter_id));
CREATE TABLE subject_removals(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id),question_id TEXT NOT NULL UNIQUE REFERENCES questions(id),subject_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL DEFAULT 'pending',reviewed_by TEXT REFERENCES users(id),reviewed_at TIMESTAMPTZ);
CREATE TABLE removal_appeals(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id),question_id TEXT NOT NULL REFERENCES questions(id),user_id TEXT NOT NULL REFERENCES users(id),reason TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL DEFAULT 'pending',UNIQUE(question_id,user_id));
CREATE TABLE admin_recoveries(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES groups(id),admin_id TEXT NOT NULL REFERENCES users(id),requested_at TIMESTAMPTZ NOT NULL,deadline_at TIMESTAMPTZ NOT NULL,status TEXT NOT NULL DEFAULT 'pending',resolved_at TIMESTAMPTZ,new_admin_id TEXT REFERENCES users(id));
CREATE UNIQUE INDEX one_pending_recovery ON admin_recoveries(group_id) WHERE status='pending';
CREATE TABLE admin_recovery_requests(recovery_id TEXT NOT NULL REFERENCES admin_recoveries(id),user_id TEXT NOT NULL REFERENCES users(id),requested_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(recovery_id,user_id));
